definition.script:
import groovy.json.JsonSlurper;

@NonCPS
def parseBuildSpec(String text) {
    def spec = new JsonSlurper().parseText(text)
    return [
        infrastructureGitHash: spec.infrastructure_git_hash?.toString(),
        bannerDeployment: spec.banner_rollout?.deployment?.toString(),
        bannerTupleSha256: spec.banner_rollout?.tupleSha256?.toString(),
        bannerRolloutPresent: spec.banner_rollout != null
    ]
}

def retrieveDepStateId
def retrieveBuildSpecId
def stacksJson
def target_stack
def live_stack
def infrastructure_git_hash
def banner_deployment
def banner_tuple_sha256
def banner_rollout_present = false
def banner_forward = false
def release_control_commit
def aim_attestation_json = ''

pipeline {
    agent any

    environment {
        SOURCE_SCRIPTS_FOLDER = "${JENKINS_HOME}/workspace/Bash_Functions/"
    }

    stages {
        stage('Retrieve Build Spec') {
            steps {
                script {
                    def result = build job: 'Retrieve Build Spec', parameters: [[$class: 'StringParameterValue', name: 'RELEASE_CONTROL_BRANCH', value: params.deployment_git_hash]]
                    retrieveBuildSpecId = result.number
                }
                script {
                    copyArtifacts filter: '*', projectName: 'Retrieve Build Spec', selector: specific(""+retrieveBuildSpecId)
                    sh 'cat build-spec.json'
                    sh 'cat pipeline_git_commit.txt'
                    sh 'pwd'
                    def parsedBuildSpec = parseBuildSpec(readFile('build-spec.json'))
                    infrastructure_git_hash = parsedBuildSpec.infrastructureGitHash
                    banner_deployment = parsedBuildSpec.bannerDeployment
                    banner_tuple_sha256 = parsedBuildSpec.bannerTupleSha256
                    banner_rollout_present = parsedBuildSpec.bannerRolloutPresent
                    release_control_commit = readFile('pipeline_git_commit.txt').trim()
                }
            }
        }
        stage('Validate Banner Rollout Input') {
            steps {
                script {
                    if (banner_rollout_present != params.BANNER_ROLLOUT) {
                        error('BANNER_ROLLOUT must match the exact retrieved release input')
                    }
                    if (banner_rollout_present) {
                        if (params.BANNER_EXPECTED_DEPLOYMENT != banner_deployment || params.BANNER_EXPECTED_TUPLE_SHA256 != banner_tuple_sha256) {
                            error('Banner operator context must match the exact retrieved deployment and tuple')
                        }
                        def buildCauses = currentBuild.getBuildCauses()
                        def manualUserCauses = currentBuild.getBuildCauses('hudson.model.Cause$UserIdCause')
                        if (params.BANNER_MANUAL_OPERATOR_MODE) {
                            if (params.BANNER_ROLLOUT_OPERATION != 'FORWARD' || buildCauses.size() != 1 || manualUserCauses.size() != 1 || !manualUserCauses[0].userId) {
                                error('Manual banner mode requires one identified Jenkins operator cause')
                            }
                        } else if (!buildCauses.isEmpty()) {
                            error('Automated banner mode requires the action-only Check For Updates caller')
                        }
                        if (!(banner_deployment in ['BDC', 'AIM-AHEAD'])) {
                            error("Unsupported banner rollout deployment: ${banner_deployment}")
                        }
                        def aim_attestation = ''
                        if (banner_deployment == 'AIM-AHEAD') {
                            def runtime_attestation = "${env.JENKINS_HOME}/banner-rollout/aim-ahead-operator-attestation.json"
                            if (!fileExists(runtime_attestation)) {
                                error('AIM-AHEAD requires the separate runtime operator attestation')
                            }
                            aim_attestation_json = readFile(runtime_attestation)
                            writeFile file: 'aim-ahead-operator-attestation.json', text: aim_attestation_json
                            aim_attestation = '--attestation aim-ahead-operator-attestation.json'
                        }
                        sh """python3 "${JENKINS_HOME}/banner-rollout/validate-banner-rollout.py" \
                            --deployment '${banner_deployment}' \
                            --operation '${params.BANNER_ROLLOUT_OPERATION}' \
                            --build-spec build-spec.json \
                            --jenkins-source-commit '${env.JENKINS_SOURCE_COMMIT}' \
                            --release-control-commit '${release_control_commit}' \
                            --controller-deployment '${env.BANNER_CONTROLLER_DEPLOYMENT}' \
                            --artifact-bucket '${params.STACK_S3_BUCKET}' \
                            --controller-artifact-bucket '${env.stack_s3_bucket}' \
                            ${aim_attestation} \
                            --run-database-migrations true \
                            --include-api true \
                            --include-psama true \
                            --include-frontend true"""
                    }
                    banner_forward = banner_rollout_present && params.BANNER_ROLLOUT_OPERATION == 'FORWARD'
                }
            }
        }
        stage('Acquire and lock deployment state') {
            steps {
                script {
                    def result = build job: 'Retrieve Deployment State'
                    retrieveDepStateId = result.number
                }
                script {
                    copyArtifacts filter: '*', projectName: 'Retrieve Deployment State', selector: specific(""+retrieveDepStateId)
                    sh 'cat stacks.json'
                    stacksJson = new File('/var/jenkins_home/workspace/Deployment Pipeline/stacks.json').text
                }
            }
        }
        stage('Create Auth & Picsure Database Backups') {
            steps {
                parallel (
                    authSchema: {
                        script {
                            def authSchema = "auth"
                            def result = build job: 'Database Backup', parameters: [[$class: 'StringParameterValue', name: 'SOURCE_DATABASE', value: authSchema]]
                        }
                    },
                    picsureSchema: {
                        script {
                            def picsureSchema = "picsure"
                            def result = build job: 'Database Backup', parameters: [[$class: 'StringParameterValue', name: 'SOURCE_DATABASE', value: picsureSchema]]
                        }
                    }
                )
            }
        }
        stage('Database Migrations') {
            steps {
                script {
                    def result = build job: 'Database Migrations', parameters: [[$class: 'StringParameterValue', name: 'infrastructure_git_hash', value: infrastructure_git_hash]]
                }
            }
        }
        stage('Update PIC-SURE Token Introspection Token') {
            steps {
                script {
                    def result = build job: 'Update PIC-SURE Token Introspection Token'
                }
            }
        }
        stage('Render Config Templates') {
            steps {
                script {
                    target_stack = new JsonSlurper().parseText(stacksJson).environments.next_prod
                    live_stack = new JsonSlurper().parseText(stacksJson).environments.prod
                    parallel(
                        hpds: {
                            build job: 'Render HPDS Config Templates', parameters: [[$class: 'StringParameterValue', name: 'INFRASTRUCTURE_GIT_HASH', value: infrastructure_git_hash], [$class: 'StringParameterValue', name: 'TARGET_STACK', value: target_stack], [$class: 'BooleanParameterValue', name: 'RENDER_AUTH_HPDS', value: true], [$class: 'BooleanParameterValue', name: 'RENDER_OPEN_HPDS', value: true]]
                        },
                        visualization: {
                            build job: 'Render PIC-SURE Visualization Config Template', parameters: [[$class: 'StringParameterValue', name: 'INFRASTRUCTURE_GIT_HASH', value: infrastructure_git_hash], [$class: 'StringParameterValue', name: 'TARGET_STACK', value: target_stack]]
                        },
                        picsure_services: {
                            build job: 'Render PIC-SURE Service Config Templates', parameters: [[$class: 'StringParameterValue', name: 'INFRASTRUCTURE_GIT_HASH', value: infrastructure_git_hash], [$class: 'StringParameterValue', name: 'TARGET_STACK', value: target_stack]]
                        }
                    )
                }
            }
        }
        stage('Teardown and Rebuild Stage Environment') {
            steps {
                script {
                    def result = build job: 'Teardown and Rebuild Stage Environment', parameters: [[$class: 'StringParameterValue', name: 'live_stack', value: live_stack], [$class: 'StringParameterValue', name: 'target_stack', value: target_stack], [$class: 'StringParameterValue', name: 'dataset_s3_object_key', value: env.dataset_s3_object_key], [$class: 'StringParameterValue', name: 'destigmatized_dataset_s3_object_key', value: env.destigmatized_dataset_s3_object_key], [$class: 'StringParameterValue', name: 'genomic_dataset_s3_object_key', value: env.genomic_dataset_s3_object_key], [$class: 'StringParameterValue', name: 'deployment_git_hash', value: env.deployment_git_hash], [$class: 'StringParameterValue', name: 'infrastructure_git_hash', value: infrastructure_git_hash], [$class: 'BooleanParameterValue', name: 'BOOTSTRAP_STANDARD_CRITICAL_ARTIFACTS', value: !banner_forward], [$class: 'StringParameterValue', name: 'BANNER_VALIDATED_UPSTREAM_RUN_ID', value: banner_forward ? "deployment-${env.BUILD_NUMBER}" : ''], [$class: 'StringParameterValue', name: 'BANNER_VALIDATED_INFRASTRUCTURE_COMMIT', value: banner_forward ? infrastructure_git_hash : '']]
                }
            }
        }
        stage('Await Initialization') {
            steps {
                script {
                    def result = build job: 'Await Initialization', parameters: [[$class: 'StringParameterValue', name: 'target_stack', value: target_stack], [$class: 'StringParameterValue', name: 'git_hash', value: infrastructure_git_hash], [$class: 'StringParameterValue', name: 'deployment_git_hash', value: params.deployment_git_hash], [$class: 'BooleanParameterValue', name: 'WAIT_FOR_TARGET_GROUP_HEALTH', value: !banner_forward], [$class: 'StringParameterValue', name: 'BANNER_VALIDATED_UPSTREAM_RUN_ID', value: banner_forward ? "deployment-${env.BUILD_NUMBER}" : ''], [$class: 'StringParameterValue', name: 'BANNER_VALIDATED_INFRASTRUCTURE_COMMIT', value: banner_forward ? infrastructure_git_hash : ''], [$class: 'StringParameterValue', name: 'BANNER_VALIDATED_DEPLOYMENT', value: banner_forward ? banner_deployment : ''], [$class: 'StringParameterValue', name: 'BANNER_VALIDATED_TUPLE_SHA256', value: banner_forward ? banner_tuple_sha256 : '']]
                }
            }
        }
        stage('Banner Rollout: Build, Backend, then Frontend') {
            when {
                expression { return params.BANNER_ROLLOUT }
            }
            steps {
                script {
                    build job: 'PIC-SURE Pipeline Build and Deploy', parameters: [
                        [$class: 'StringParameterValue', name: 'RELEASE_CONTROL_BRANCH', value: params.deployment_git_hash],
                        [$class: 'StringParameterValue', name: 'TARGET_STACK', value: 'staging'],
                        [$class: 'StringParameterValue', name: 'DATASET_S3_OBJECT_KEY', value: params.dataset_s3_object_key],
                        [$class: 'StringParameterValue', name: 'DESTIGMATIZED_DATASET_S3_OBJECT_KEY', value: params.destigmatized_dataset_s3_object_key],
                        [$class: 'StringParameterValue', name: 'GENOMIC_DATASET_S3_OBJECT_KEY', value: params.genomic_dataset_s3_object_key],
                        [$class: 'StringParameterValue', name: 'STACK_S3_BUCKET', value: params.STACK_S3_BUCKET],
                        [$class: 'StringParameterValue', name: 'BANNER_AIM_ATTESTATION_JSON', value: aim_attestation_json],
                        [$class: 'StringParameterValue', name: 'BANNER_ROLLOUT_OPERATION', value: params.BANNER_ROLLOUT_OPERATION],
                        [$class: 'BooleanParameterValue', name: 'MIGRATIONS_COMPLETED_UPSTREAM', value: true],
                        [$class: 'BooleanParameterValue', name: 'RUN_DATABASE_MIGRATIONS', value: true],
                        [$class: 'BooleanParameterValue', name: 'INCLUDE_PIC_SURE_API', value: true],
                        [$class: 'BooleanParameterValue', name: 'INCLUDE_PIC_SURE_AUTH_MICRO_APP', value: true],
                        [$class: 'BooleanParameterValue', name: 'INCLUDE_PIC_SURE_FRONTEND', value: true]
                    ]
                }
            }
        }
        stage('Banner Rollout: Confirm Final Health') {
            when {
                expression { return banner_forward }
            }
            steps {
                script {
                    build job: 'Await Initialization', parameters: [[$class: 'StringParameterValue', name: 'target_stack', value: target_stack], [$class: 'StringParameterValue', name: 'git_hash', value: infrastructure_git_hash], [$class: 'BooleanParameterValue', name: 'WAIT_FOR_TARGET_GROUP_HEALTH', value: true]]
                }
            }
        }
        stage('Falcon Sensor Check') {
            steps {
                script {
                    def result = build job: 'Falcon Sensor Check', parameters: [[$class: 'StringParameterValue', name: 'target_stack', value: target_stack], [$class: 'StringParameterValue', name: 'git_hash', value: infrastructure_git_hash]]
                }
            }
        }
    }
    post {
        always {
            script {
                if (stacksJson?.trim()) {
                    def result = build job: 'Write Stack State', parameters: [[$class: 'StringParameterValue', name: 'stacks_json', value: stacksJson]]
                } else {
                    echo "stacksJson was never assigned — skipping Write Stack State to avoid corrupting the state file."
                }
            }
        }
    }
}
